import sys
from heapq import heappush, heappop

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); k = int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    small = []  # max-heap via negation, holds the lower half
    large = []  # min-heap, holds the upper half
    delayed = {}
    ss = ls = 0
    out = []
    for i in range(n):
        x = a[i]
        if not small or x <= -small[0]:
            heappush(small, -x); ss += 1
        else:
            heappush(large, x); ls += 1
        if i >= k:
            y = a[i - k]
            delayed[y] = delayed.get(y, 0) + 1
            if y <= -small[0]:
                ss -= 1
                if y == -small[0]:
                    while small and delayed.get(-small[0], 0) > 0:
                        delayed[-small[0]] -= 1
                        heappop(small)
            else:
                ls -= 1
                if y == large[0]:
                    while large and delayed.get(large[0], 0) > 0:
                        delayed[large[0]] -= 1
                        heappop(large)
        if ss > ls + 1:
            heappush(large, -heappop(small)); ss -= 1; ls += 1
            while small and delayed.get(-small[0], 0) > 0:
                delayed[-small[0]] -= 1
                heappop(small)
        elif ss < ls:
            heappush(small, -heappop(large)); ls -= 1; ss += 1
            while large and delayed.get(large[0], 0) > 0:
                delayed[large[0]] -= 1
                heappop(large)
        if i >= k - 1:
            if k % 2:
                out.append(-2 * small[0])
            else:
                out.append(-small[0] + large[0])
    print(' '.join(map(str, out)))

